sys_script_include.script:
var CapacityValidator = Class.create();
CapacityValidator.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getCurrentOccupancy: function(scheduleSysId) {
        var grEnrollment = new GlideAggregate('x_752538_course_enrollment');
        grEnrollment.addQuery('date', scheduleSysId);
        grEnrollment.addQuery('status', 'IN', '2,3');
        grEnrollment.addAggregate('COUNT');
        grEnrollment.query();

        var count = 0;
        if (grEnrollment.next()) {
            count = parseInt(grEnrollment.getAggregate('COUNT'), 10);
        }
        return count;
    },

    checkCapacity: function() {
        var scheduleSysId = this.getParameter('sysparm_schedule_sys_id');

        if (!scheduleSysId) return 'false';

        var grSchedule = new GlideRecord('x_752538_course_schedule');
        if (grSchedule.get(scheduleSysId)) {
            var capacityMax = parseInt(grSchedule.capacity_max);
            var currentOccupancy = this.getCurrentOccupancy(scheduleSysId);
            var potentialOccupancy = currentOccupancy + 1;

            if (potentialOccupancy > capacityMax) {

                return potentialOccupancy.toString();
            } else {
                return 'true';
            }
        }

        return 'false';
    },

    type: 'CapacityValidator'
});
